<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$projects=$db->query("SELECT p.id,p.name,COALESCE(r.revenue,0) revenue,COALESCE(x.cost,0) cost,COALESCE(r.revenue,0)-COALESCE(x.cost,0) profit FROM client_projects p LEFT JOIN (SELECT project_id,SUM(total) revenue FROM invoices WHERE status<>'cancelled' GROUP BY project_id) r ON r.project_id=p.id LEFT JOIN (SELECT project_id,SUM(amount) cost FROM expenses WHERE status='recorded' GROUP BY project_id) x ON x.project_id=p.id ORDER BY profit DESC")->fetchAll();$clients=$db->query("SELECT c.id,c.name,COALESCE(r.revenue,0) revenue,COALESCE(x.cost,0) cost,COALESCE(r.revenue,0)-COALESCE(x.cost,0) profit FROM clients c LEFT JOIN (SELECT client_id,SUM(total) revenue FROM invoices WHERE status<>'cancelled' GROUP BY client_id) r ON r.client_id=c.id LEFT JOIN (SELECT client_id,SUM(amount) cost FROM expenses WHERE status='recorded' GROUP BY client_id) x ON x.client_id=c.id ORDER BY profit DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profitability</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Profitability</h1><div class="card mb-4"><div class="card-body"><h2 class="h5">Project Profitability</h2><table class="table"><thead><tr><th>Project</th><th>Revenue</th><th>Cost</th><th>Profit</th></tr></thead><tbody><?php foreach($projects as $r):?><tr><td><?=$e($r['name'])?></td><td><?=number_format((float)$r['revenue'],2)?></td><td><?=number_format((float)$r['cost'],2)?></td><td><strong><?=number_format((float)$r['profit'],2)?></strong></td></tr><?php endforeach;?></tbody></table></div></div><div class="card"><div class="card-body"><h2 class="h5">Client Profitability</h2><table class="table"><thead><tr><th>Client</th><th>Revenue</th><th>Cost</th><th>Profit / LTV</th></tr></thead><tbody><?php foreach($clients as $r):?><tr><td><?=$e($r['name'])?></td><td><?=number_format((float)$r['revenue'],2)?></td><td><?=number_format((float)$r['cost'],2)?></td><td><strong><?=number_format((float)$r['profit'],2)?></strong></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>